const revealEls = document.querySelectorAll('.reveal');const io = new IntersectionObserver((entries) => {entries.forEach(e => {if (e.isIntersecting) {e.target.classList.add('is-visible');io.unobserve(e.target);}});}, { threshold: 0.12 });revealEls.forEach(el => io.observe(el));const menuBtn = document.getElementById('menuBtn');const navlinks = document.getElementById('navlinks');if (menuBtn && navlinks) {menuBtn.addEventListener('click', () => {navlinks.classList.toggle('is-open');menuBtn.classList.toggle('is-open');const open = navlinks.classList.contains('is-open');menuBtn.setAttribute('aria-expanded', open ? 'true' : 'false');});navlinks.querySelectorAll('a').forEach(a => {a.addEventListener('click', () => {navlinks.classList.remove('is-open');menuBtn.classList.remove('is-open');menuBtn.setAttribute('aria-expanded', 'false');});});}const contactForm = document.getElementById('contactForm');if (contactForm) {contactForm.addEventListener('submit', (e) => {e.preventDefault();const honeypot = contactForm.querySelector('.honeypot');if (honeypot && honeypot.value.trim() !== '') {return;}const nombre = contactForm.querySelector('[name="nombre"]').value.trim();const negocio = contactForm.querySelector('[name="negocio"]').value.trim();const mensaje = contactForm.querySelector('[name="mensaje"]').value.trim();let texto = `Hola RDV SYSTEMS, soy ${nombre}.`;if (negocio) texto += ` Mi negocio es ${negocio}.`;texto += ` Quisiera más información: ${mensaje}`;const numero = '573223690657';const url = `https://wa.me/${numero}?text=${encodeURIComponent(texto)}`;window.open(url, '_blank');});}const waChat = document.querySelector('.wa-chat');const waBtn = document.getElementById('waBtn');if (waChat && waBtn) {waBtn.addEventListener('click', () => {const open = waChat.classList.toggle('is-open');waBtn.setAttribute('aria-expanded', open ? 'true' : 'false');});document.addEventListener('click', (e) => {if (!waChat.contains(e.target)) {waChat.classList.remove('is-open');waBtn.setAttribute('aria-expanded', 'false');}});}function animateCount(el) {const target = parseInt(el.getAttribute('data-target'), 10);const duration = 1200;const start = performance.now();function frame(now) {const progress = Math.min((now - start) / duration, 1);const eased = 1 - Math.pow(1 - progress, 3);el.textContent = Math.round(target * eased);if (progress < 1) requestAnimationFrame(frame);}requestAnimationFrame(frame);}const countEls = document.querySelectorAll('.count-to');if (countEls.length && 'IntersectionObserver' in window) {const countIO = new IntersectionObserver((entries) => {entries.forEach(entry => {if (entry.isIntersecting) {animateCount(entry.target);countIO.unobserve(entry.target);}});}, { threshold: 0.5 });countEls.forEach(el => countIO.observe(el));}const headerEl = document.querySelector('header');if (headerEl) {const onScroll = () => {headerEl.classList.toggle('scrolled', window.scrollY > 40);};window.addEventListener('scroll', onScroll, { passive: true });onScroll();}if (window.matchMedia('(hover: hover) and (pointer: fine)').matches) {document.querySelectorAll('.card, .portfolio-card').forEach(card => {card.addEventListener('mousemove', (e) => {const r = card.getBoundingClientRect();const x = (e.clientX - r.left) / r.width - 0.5;const y = (e.clientY - r.top) / r.height - 0.5;card.style.setProperty('--rx', `${(-y * 6).toFixed(2)}deg`);card.style.setProperty('--ry', `${(x * 6).toFixed(2)}deg`);});card.addEventListener('mouseleave', () => {card.style.setProperty('--rx', '0deg');card.style.setProperty('--ry', '0deg');});});}const heroBg = document.querySelector('.hero-bg');if (heroBg) {window.addEventListener('scroll', () => {const y = window.scrollY;if (y < window.innerHeight) {heroBg.style.transform = `translate3d(0, ${(y * 0.18).toFixed(1)}px, 0)`;}}, { passive: true });}const yearEl = document.getElementById('year');if (yearEl) {yearEl.textContent = new Date().getFullYear();}